import assert from 'node:assert/strict';
import {normalizeCode} from './normalize.mjs';
const valid = [[' ab-12 ', 'AB-12'], ['a0','A0'], ['Z9-Z','Z9-Z']];
for (const [input, expected] of valid) assert.equal(normalizeCode(input), expected);
for (const input of ['', ' ', 'a', 'a_b', 'a b', 'éa', 'ßa', 'a–b', 'a'.repeat(13)]) assert.throws(() => normalizeCode(input), RangeError, JSON.stringify(input));
for (const input of [null, undefined, 123, {}, ['ab']]) assert.throws(() => normalizeCode(input), TypeError);
assert.equal(normalizeCode('a'.repeat(12)), 'A'.repeat(12));
console.log('PASS: string-only, trimmed ASCII letters/digits/hyphen, length 2..12, uppercase output; Unicode rejected before casing.');

after_implementation.content:
const CODE_PATTERN = /^[A-Za-z0-9-]{2,12}$/;

export function normalizeCode(value) {
  if (typeof value !== 'string') {
    throw new TypeError(`normalizeCode expects a string, received ${typeof value}`);
  }
  const trimmed = value.trim();
  if (!CODE_PATTERN.test(trimmed)) {
    throw new RangeError(
      'normalizeCode expects 2..12 ASCII letters, digits or hyphens after trimming',
    );
  }
  return trimmed.toUpperCase();
}

