after_style.content:
:root {
  --cream: #f6f0e5;
  --forest: #163e3a;
  --forest-deep: #0f2d2a;
  --rule: #8faaa4;
  --focus: #af600e;
  --space-2: 12px;
  --space-3: 16px;
  --space-5: 32px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  background: var(--cream);
  color: var(--forest);
  font: 17px/1.6 Georgia, serif;
}

main {
  max-width: 1024px;
  margin: auto;
  padding: clamp(32px, 5vw, 56px) clamp(24px, 4vw, 32px);
}

header {
  margin-bottom: clamp(24px, 3vw, var(--space-5));
}

.eyebrow {
  margin: 0 0 var(--space-2);
  font: 12px/1.5 system-ui;
  letter-spacing: .15em;
}

h1 {
  margin: 0 0 var(--space-3);
  font-size: 44px;
  line-height: 1.2;
}

header p:not(.eyebrow) {
  margin: 0;
  max-width: 52ch;
}

section {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: clamp(16px, 2vw, 24px);
  margin-bottom: clamp(24px, 3vw, var(--space-5));
}

article {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  border: 1px solid var(--rule);
  padding: clamp(16px, 2.2vw, 24px);
}

h2 {
  margin: 0;
  font-size: 23px;
  line-height: 1.3;
}

article p {
  margin: 0;
}

button {
  align-self: flex-start;
  margin-top: auto;
  background: var(--forest);
  color: #fff;
  border: 0;
  border-radius: 3px;
  min-height: 44px;
  padding: 11px 20px;
  font: 14px/1.2 system-ui;
  cursor: pointer;
}

button:hover,
button:active {
  background: var(--forest-deep);
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 3px;
}

#progress {
  margin: 0;
}

@media (max-width: 600px) {
  section { grid-template-columns: 1fr; }
  h1 { font-size: 34px; }
}

