async page => {
  const results = [];
  const assert = (condition, label) => { if (!condition) throw new Error(label); };
  for (const [width, height] of [[390,844],[1280,900]]) {
    await page.setViewportSize({width,height});
    await page.goto('http://127.0.0.1:8765');
    const names = await page.locator('h2').allTextContents();
    assert(JSON.stringify(names)===JSON.stringify(['The Secret Garden','A Room of One’s Own','The Wind in the Willows']), 'exact book content');
    const authors = await page.locator('article p').allTextContents();
    assert(JSON.stringify(authors)===JSON.stringify(['Frances Hodgson Burnett','Virginia Woolf','Kenneth Grahame']), 'exact authors');
    const buttons=page.getByRole('button');
    assert(await buttons.count()===3,'three real buttons');
    for(let i=0;i<3;i++) {
      await buttons.nth(i).click();
      assert(await buttons.nth(i).getAttribute('aria-pressed')==='true','click toggles pressed');
      assert(await page.getByRole('status').textContent()===`${i+1} of 3 finished`,'live progress count');
    }
    await page.reload();
    await page.keyboard.press('Tab');
    for(let i=0;i<3;i++) {
      assert(await buttons.nth(i).evaluate(b=>b===document.activeElement),'keyboard order');
      await page.keyboard.press(i===1?'Space':'Enter');
      assert(await buttons.nth(i).getAttribute('aria-pressed')==='true','keyboard toggles');
      if(i<2) await page.keyboard.press('Tab');
    }
    assert(await page.getByRole('status').textContent()==='3 of 3 finished','keyboard progress');
    const layout=await page.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth,heights:[...document.querySelectorAll('button')].map(b=>b.getBoundingClientRect().height),focus:{width:getComputedStyle(document.activeElement).outlineWidth,style:getComputedStyle(document.activeElement).outlineStyle},live:document.querySelector('#progress').getAttribute('aria-live'),background:getComputedStyle(document.body).backgroundColor,color:getComputedStyle(document.body).color,font:getComputedStyle(document.body).fontFamily}));
    assert(layout.scrollWidth<=width,'no horizontal overflow');assert(layout.heights.every(h=>h>=44),'44px comfortable target');assert(layout.focus.width==='3px'&&layout.focus.style==='solid','visible keyboard focus');assert(layout.live==='polite','polite progress announcement');
    for(let i=0;i<3;i++) await buttons.nth(i).click();
    assert(await page.getByRole('status').textContent()==='0 of 3 finished','toggle reversal');
    await page.emulateMedia({reducedMotion:'reduce'});
    results.push({width,height,passed:true,layout});
  }
  return {passed:true,runtime:await page.evaluate(()=>navigator.userAgent),checks:results,limits:'Chromium DOM and keyboard checks, no screen-reader session or cross-browser claim'};
}
